-- RAG store. __EMBED_DIM__ is substituted with settings.embed_dim by
-- scripts/migrate.py before execution (768 for nomic-embed-text).

CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE IF NOT EXISTS chunks (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    doc_id       TEXT NOT NULL,
    heading_path TEXT NOT NULL,
    content      TEXT NOT NULL,
    content_hash TEXT NOT NULL UNIQUE,
    embedding    vector(__EMBED_DIM__),
    metadata     JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS chunks_embedding_hnsw
    ON chunks USING hnsw (embedding vector_cosine_ops);

-- ADR-006: the query picks 'portuguese'/'english' per request (mixed pt-BR/EN
-- alerts), so a per-language functional index would go unused. Index the
-- language-neutral 'simple' config as a broad @@ safety net; on a table this
-- small (tens of chunks) a seq scan for ranking is instant anyway.
DROP INDEX IF EXISTS chunks_content_fts;
CREATE INDEX IF NOT EXISTS chunks_content_fts_simple
    ON chunks USING gin (to_tsvector('simple', content));

CREATE INDEX IF NOT EXISTS chunks_doc_id_idx ON chunks (doc_id);
